import{_ as r,C as o,o as n,c as l,a2 as a,E as s}from"./chunks/framework.BSaF8iZ6.js";const c=JSON.parse('{"title":"Payment Requests & Payouts","description":"","frontmatter":{},"headers":[],"relativePath":"payments/payment-management.md","filePath":"payments/payment-management.md","lastUpdated":1789411447000}'),d={name:"payments/payment-management.md"};function i(m,e,h,g,p,u){const t=o("ImagePopup");return n(),l("div",null,[e[0]||(e[0]=a('<h1 id="payment-requests-payouts" tabindex="-1">Payment Requests &amp; Payouts <a class="header-anchor" href="#payment-requests-payouts" aria-label="Permalink to &quot;Payment Requests &amp; Payouts&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>Customers pay the store, and the store pays each seller what they earned. A seller requests payment for each completed order. The admin pays the seller outside the store, for example by bank transfer, and records the payment here.</p><h2 id="what-a-seller-earns" tabindex="-1">What a seller earns <a class="header-anchor" href="#what-a-seller-earns" aria-label="Permalink to &quot;What a seller earns&quot;">​</a></h2><p>For each order, a seller earns the invoiced value of their products, minus any discount and the store&#39;s commission, plus the tax. Shipping isn&#39;t included. See <a href="./commission-management">Commission</a>.</p><h2 id="request-payment" tabindex="-1">Request payment <a class="header-anchor" href="#request-payment" aria-label="Permalink to &quot;Request payment&quot;">​</a></h2><p>Sellers can request payment for an order once their part of it is <strong>Completed</strong> and there is something left to pay.</p><ol><li>Go to <strong>Sales &gt;&gt; Orders</strong>.</li><li>Click <strong>Request Payment</strong> on the order&#39;s row.</li><li>Confirm.</li></ol>',8)),s(t,{src:"/images/payment-management/request-payment.png",alt:"Request Payment on a completed order"}),e[1]||(e[1]=a('<p>You&#39;ll see <strong>Your payment request is submitted successfully</strong>. The order&#39;s <strong>Seller Payment Status</strong> changes to <strong>Requested</strong>, and the store admin receives a <strong>Seller Payment Request Notification</strong> email.</p><p>If any item in an order is refunded, even partly, the order&#39;s <strong>Seller Payment Status</strong> becomes <strong>Refunded</strong>. It can&#39;t be requested, and it leaves the admin&#39;s <strong>Payment Requests</strong> list. This also happens if the order was already paid.</p><h2 id="pay-a-seller" tabindex="-1">Pay a seller <a class="header-anchor" href="#pay-a-seller" aria-label="Permalink to &quot;Pay a seller&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Sales &gt;&gt; Payment Requests</strong>.</li><li>Click <strong>Pay Now</strong> on the order.</li><li>In <strong>Payment to Seller</strong>, enter a <strong>Comment</strong>, such as your bank transfer reference.</li><li>Click <strong>Pay Now</strong>.</li></ol>',4)),s(t,{src:"/images/payment-management/payout-management.png",alt:"The Seller Payout Management page"}),s(t,{src:"/images/payment-management/pay-seller.png",alt:"The Payment to Seller dialog"}),e[2]||(e[2]=a('<p>You&#39;ll see <strong>Seller is Paid successfully!</strong>. Each payment covers the whole amount still owed for that order. A transaction is recorded, the order&#39;s <strong>Seller Payment Status</strong> changes to <strong>Paid</strong>, and the seller receives an email. See <a href="./transactions">Transactions</a>.</p><p>The page lists only orders sellers have requested payment for. At the top:</p><table tabindex="0"><thead><tr><th>Card</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Payable Orders</strong></td><td>How many requested orders are waiting to be paid</td></tr><tr><td><strong>Unpaid Payout Amount</strong></td><td>How much is owed for those orders</td></tr><tr><td><strong>Total Commission Earned</strong></td><td>The commission on orders that have been paid</td></tr><tr><td><strong>Unpaid Sellers</strong></td><td>How many sellers are waiting to be paid, out of all sellers with requests or payments</td></tr></tbody></table><p>Each order shows its number, date and status, the customer, the amounts, the seller and shop, and how much has been paid so far.</p><h3 id="pay-several-sellers-at-once" tabindex="-1">Pay several sellers at once <a class="header-anchor" href="#pay-several-sellers-at-once" aria-label="Permalink to &quot;Pay several sellers at once&quot;">​</a></h3><ol><li>Go to <strong>Marketplace &gt;&gt; Sales &gt;&gt; Payment Requests</strong>.</li><li>Tick the orders.</li><li>Click <strong>Select Action &gt;&gt; Pay Now</strong>.</li></ol>',6)),s(t,{src:"/images/payment-management/mass-pay.png",alt:"Paying several orders at once"}),e[3]||(e[3]=a('<p>Each order is paid in full, with the comment <strong>Paid Out of system</strong>, and each seller receives an email for each order.</p><h2 id="payment-statuses" tabindex="-1">Payment statuses <a class="header-anchor" href="#payment-statuses" aria-label="Permalink to &quot;Payment statuses&quot;">​</a></h2><p>The <strong>Seller Payment Status</strong> column on the seller&#39;s orders shows where each order stands. Team members see it only with the <strong>Payment Request</strong> permission.</p><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td>No status, with a <strong>Request Payment</strong> button</td><td>The order is completed and payment can be requested.</td></tr><tr><td><strong>Invoice Pending</strong></td><td>Nothing is ready to request yet, for example the order isn&#39;t invoiced.</td></tr><tr><td><strong>Processing</strong></td><td>Part of the order is invoiced, but it isn&#39;t completed yet.</td></tr><tr><td><strong>Requested</strong></td><td>The seller has requested payment.</td></tr><tr><td><strong>Paid</strong></td><td>The store has paid the seller for the order.</td></tr><tr><td><strong>Refunded</strong></td><td>Something in the order was refunded, so it can&#39;t be requested.</td></tr><tr><td><strong>Canceled</strong></td><td>The seller&#39;s part of the order was cancelled.</td></tr></tbody></table><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>The store doesn&#39;t send the money. Pay the seller first, then record it here.</li><li>There is no way to pay part of an order&#39;s amount from this page.</li><li>Sellers follow their payments on <a href="./transactions">Transactions</a>.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><ul><li>Team members need <strong>Orders</strong> with <strong>Payment Request</strong> to request payment.</li><li>Admins need <strong>Marketplace &gt;&gt; Sales &gt;&gt; Payment Request</strong> with <strong>Pay</strong>.</li></ul>',8))])}const P=r(d,[["render",i]]);export{c as __pageData,P as default};
